effect.shader:
float rand(vec2 c){ return fract(sin(dot(c,vec2(12.9898,78.233)))*43758.5453); }
void main(){
    vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
    vec2 uv = acScreenNorm;
    vec2 g = uv*vec2(40.0*amount+10.0, 8.0);
    g.y += acTime*speed*3.0;
    vec2 id = floor(g);
    vec2 f = fract(g);
    float h = rand(id);
    float drop = smoothstep(0.5,0.0,abs(f.x-0.5)*2.0) * smoothstep(1.0,0.0,f.y) * step(0.78,h);
    gl_FragColor = src + vec4(color.rgb,0.0)*drop*0.7;
}
